/*
 * SpiderLoadingScreen.js - lightweight loading screen for Escape from Spider.
 *
 * Same look and behaviour as loadingScreen.js (asset 216306160, 365,740 bytes), which
 * embedded a 1920x1080 JPEG background (62 KB) and a 1373x817 PNG logo (206 KB) as base64:
 *  - logo: 960x571 WebP with full alpha (quality 0.85), about 114 KB. The earlier 480x286 version
 *    with alpha cut to 8 levels showed a grey halo around the letters. Shown at 40% of the
 *    viewport width, so 960 px stays sharp up to 2400 px wide screens.
 *  - background: 800x450 WebP (quality 0.8), about 10 KB: a lightly blurred shot of the
 *    DontSplash pool monster (colours untouched), placed on the right so the logo and bar in
 *    the middle stay clear; the picture is anchored right (background-position) so narrower
 *    screens keep the monster. A gradient of its colours paints underneath until it has decoded.
 *  - the splash is visible at once (the logo's box is reserved) instead of staying hidden
 *    until the logo has decoded.
 *  - removed dead code: the @font-face for asset 121143033 (not in this project; app.assets
 *    is still empty when this runs), the app.start pass-through wrapper (app.startOld), and
 *    the sideways background animation of the bar (its gradient is vertical, so it never
 *    changed a pixel but repainted every frame).
 * WebP is safe: engine 2.x needs WebGL2, and every browser that has WebGL2 decodes WebP.
 *
 * Rollback: Settings > Loading Screen > select loadingScreen.js (216306160) again.
 */
pc.script.createLoadingScreen(function (app) {
    // Also set by the old loading screen; kept so anything relying on them keeps working.
    app.firstLoad = true;
    app.logo = 'data:image/webp;base64,';

    var bg = 'url(data:image/webp;base64,),linear-gradient(#27221e,#27201d 25%,#3d4e5b 50%,#556068)';

    var css = [
        'body{background-color:#3b4248;background-image:' + bg + ';background-size:100% 100%}',
        '#application-splash-wrapper{position:absolute;top:0;left:0;width:100%;height:100%;background-color:#3b4248;background-image:' + bg + ';background-size:cover;background-position:right center}',
        '#application-splash{position:fixed;width:40%;top:50%;left:50%;transform:translate(-50%,-50%)}',
        '#application-splash img{width:100%;height:auto;animation:bounce 1.5s infinite}',
        '#progress-bar-container{border-radius:15px;margin:0 auto;height:25px;width:100%;background-color:#171717;border:4px solid #171717}',
        '#progress-bar{border-radius:15px;width:0%;height:100%;background:linear-gradient(180deg,#7cff83,#00ff0d,#00da0b);box-shadow:inset 0 2px 5px #05c70e}',
        '#progress-status{position:relative;bottom:95%;text-align:center;font-family:Impact,sans-serif;color:#fff}',
        '#spinner::before{animation:.6s linear infinite spinner;animation-play-state:inherit;border:solid 10px #171717;border-bottom-color:#00ff44;border-radius:50%;content:"";height:20px;width:20px;position:absolute;top:calc(100% + 40px);left:50%;transform:translate3d(-50%,0,0);will-change:transform}',
        '@keyframes spinner{0%{transform:translate3d(-50%,-50%,0) rotate(0deg)}100%{transform:translate3d(-50%,-50%,0) rotate(360deg)}}',
        '@keyframes bounce{0%,20%,50%,80%,100%{transform:translateY(0)}40%{transform:translateY(-15px)}60%{transform:translateY(-7px)}}'
    ].join('\n');

    var style = document.createElement('style');
    style.textContent = css;
    document.head.appendChild(style);

    // Same element ids as before.
    var wrapper = document.createElement('div');
    wrapper.id = 'application-splash-wrapper';

    var splash = document.createElement('div');
    splash.id = 'application-splash';
    wrapper.appendChild(splash);

    // The width/height attributes reserve the logo's box, so nothing moves when it decodes.
    var logo = new Image(960, 571);
    logo.alt = '';
    logo.src = app.logo;
    splash.appendChild(logo);

    var container = document.createElement('div');
    container.id = 'progress-bar-container';
    splash.appendChild(container);

    var bar = document.createElement('div');
    bar.id = 'progress-bar';
    container.appendChild(bar);

    var spinner = document.createElement('div');
    spinner.id = 'spinner';
    bar.appendChild(spinner);

    var statusText = document.createElement('div');
    statusText.id = 'progress-status';
    statusText.textContent = 'Loading..';
    container.appendChild(statusText);

    document.body.appendChild(wrapper);

    var setProgress = function (value) {
        value = Math.min(1, Math.max(0, value));
        bar.style.width = value * 100 + '%';
    };

    // "loaded / total" counter over the preloaded assets, as before.
    app.on('preload:start', function () {
        var loaded = 0;
        var total = 0;

        var onLoad = function () {
            loaded++;
            statusText.textContent = loaded / total > 0.9 ? 'Joining..' : loaded + ' / ' + total + ' loaded';
            if (loaded / total > 0.5) statusText.style.color = '#000000';
        };

        var list = app.assets.list({ preload: true });
        for (var i = 0; i < list.length; i++) {
            if (!list[i].preload) continue;
            total++;
            if (list[i].resource) onLoad();
            else list[i].once('load', onLoad);
        }

        statusText.style.color = '#ffffff';
        statusText.textContent = loaded + ' / ' + total;
    });

    app.on('preload:progress', setProgress);
    app.on('preload:end', function () {
        app.off('preload:progress', setProgress);
    });

    app.on('start', function () {
        if (wrapper.parentNode) wrapper.parentNode.removeChild(wrapper);
    });
});
